#include "lanlink/app/options.hpp"
#include <gtest/gtest.h>
#include <cmath>
#include <string>
using namespace lanlink;
using namespace lanlink::app;
namespace {
std::vector<char*> args(std::initializer_list<const char*> values) { std::vector<char*> out; for (auto v: values) out.push_back(const_cast<char*>(v)); return out; }
}
TEST(AppOptions, ParseOptionsAcceptsRequiredValuesAndDefaults) {
 auto a=args({"lanlink_app","--device-id","11","--peer-id","22","--listen-port","4000"}); auto r=parse_options((int)a.size(),a.data()); ASSERT_TRUE(r.ok())<<r.error(); EXPECT_EQ(r.value().device_id,11u); EXPECT_EQ(r.value().peer_id,22u); EXPECT_EQ(r.value().listen_port,4000); EXPECT_EQ(r.value().remote_side,RemoteSide::kRight); EXPECT_DOUBLE_EQ(r.value().width,1920.0); EXPECT_DOUBLE_EQ(r.value().height,1080.0); EXPECT_FALSE(r.value().connect.has_value());
}
TEST(AppOptions, ParseOptionsAcceptsConnectAndTopologyValues) {
 auto a=args({"x","--device-id","1","--peer-id","2","--listen-port","65535","--connect","host.example:1234","--display-id","3","--peer-display-id","4","--remote-side","left","--width","800.5","--height","600","--peer-width","1920","--peer-height","1080"}); auto r=parse_options((int)a.size(),a.data()); ASSERT_TRUE(r.ok())<<r.error(); EXPECT_EQ(r.value().connect, (transport::Endpoint{"host.example",1234})); EXPECT_EQ(r.value().display_id,3u); EXPECT_EQ(r.value().peer_display_id,4u); EXPECT_EQ(r.value().remote_side,RemoteSide::kLeft); EXPECT_DOUBLE_EQ(r.value().width,800.5); EXPECT_DOUBLE_EQ(r.value().height,600.0); EXPECT_DOUBLE_EQ(r.value().peer_width,1920.0); EXPECT_DOUBLE_EQ(r.value().peer_height,1080.0);
}
TEST(AppOptions, UsageContainsAllSupportedFlags) { auto u=usage(); for(auto f:{"--device-id","--peer-id","--listen-port","--connect","--display-id","--peer-display-id","--remote-side","--width","--height","--peer-width","--peer-height","--help"}) EXPECT_NE(u.find(f),std::string::npos); }
TEST(AppOptions, ParseOptionsRejectsMissingRequiredValues) { auto a=args({"x","--device-id","1","--peer-id","2"}); auto r=parse_options((int)a.size(),a.data()); EXPECT_FALSE(r.ok()); EXPECT_NE(r.error().find("listen-port"),std::string::npos); }
TEST(AppOptions, ParseOptionsRejectsSignedAndUnknownValues) { for(auto bad: {"-1","+1"," 1"}) { auto a=args({"x","--device-id",bad,"--peer-id","2","--listen-port","1"}); EXPECT_FALSE(parse_options((int)a.size(),a.data()).ok()); } auto a=args({"x","--device-id","1","--peer-id","2","--listen-port","1","--bogus"}); EXPECT_FALSE(parse_options((int)a.size(),a.data()).ok()); }
TEST(AppOptions, ParseOptionsRejectsMalformedConnectPortAndDimensions) { for(auto bad: {"host","host:0","host:65536","host:a","a:b:c"}) { auto a=args({"x","--device-id","1","--peer-id","2","--listen-port","1","--connect",bad}); EXPECT_FALSE(parse_options((int)a.size(),a.data()).ok())<<bad; } for(auto dim: {"0","-2","nan","inf"}) { auto a=args({"x","--device-id","1","--peer-id","2","--listen-port","1","--width",dim}); EXPECT_FALSE(parse_options((int)a.size(),a.data()).ok())<<dim; } }
TEST(AppOptions, MakeTopologyBuildsRightHandLink) { AppOptions o; o.device_id=11;o.peer_id=22;o.display_id=3;o.peer_display_id=4;o.width=800;o.height=600;o.remote_side=RemoteSide::kRight; auto r=make_topology(o); ASSERT_TRUE(r.ok())<<r.error(); auto&t=r.value(); ASSERT_EQ(t.version(),1u); ASSERT_EQ(t.displays().size(),2u); ASSERT_EQ(t.links().size(),1u); EXPECT_EQ(t.displays()[0].logical_bounds.left,0); EXPECT_EQ(t.displays()[0].logical_bounds.right,800); EXPECT_EQ(t.displays()[1].logical_bounds.left,800); EXPECT_EQ(t.displays()[1].logical_bounds.right,1600); EXPECT_EQ(t.links()[0].source_edge,Edge::kRight); EXPECT_EQ(t.links()[0].target_edge,Edge::kLeft); EXPECT_EQ(t.displays()[0].device,numeric_id(11)); EXPECT_EQ(t.displays()[1].device,numeric_id(22)); }
TEST(AppOptions, MakeTopologyBuildsLeftHandLink) { AppOptions o; o.device_id=11;o.peer_id=22;o.display_id=3;o.peer_display_id=4;o.width=800;o.height=600;o.remote_side=RemoteSide::kLeft; auto r=make_topology(o); ASSERT_TRUE(r.ok()); auto&t=r.value(); EXPECT_EQ(t.displays()[1].logical_bounds.left,-800); EXPECT_EQ(t.displays()[1].logical_bounds.right,0); EXPECT_EQ(t.links()[0].source_edge,Edge::kLeft); EXPECT_EQ(t.links()[0].target_edge,Edge::kRight); }
TEST(AppOptions, MakeTopologyAcceptsDifferentPeerDimensions) { AppOptions o; o.device_id=11;o.peer_id=22;o.display_id=3;o.peer_display_id=4;o.width=1440;o.height=900;o.peer_width=1920;o.peer_height=1080;o.remote_side=RemoteSide::kRight; auto r=make_topology(o); ASSERT_TRUE(r.ok()); auto&t=r.value(); EXPECT_EQ(t.displays()[0].logical_bounds.right,1440); EXPECT_EQ(t.displays()[1].logical_bounds.left,1440); EXPECT_EQ(t.displays()[1].logical_bounds.right,3360); EXPECT_EQ(t.displays()[1].logical_bounds.bottom,1080); }
